# Quantitative Aptitude, arithmetic: whole numbers, decimals and fractions,
# square roots, percentage, ratio and proportion, averages, interest, profit
# and loss, discount, partnership, mixture and alligation, time and distance,
# time and work (para 12.9.1.3 of the SSC CPO 2026 notice). No calculator.
# All-number options are sorted ascending by the build.
ITEMS = [
    # ---------- Practice Test 1 ----------
    S(1, 2, "Percentage", "The population of a town rose by 10% in one year and fell by 10% the next year. It is now 29,700. What was it two years ago?",
      ["30,000", "29,700", "31,000", "29,403"],
      "The population was multiplied by 1.1 and then 0.9, that is by 0.99. So the original was 29,700 ÷ 0.99 = 30,000. A 10% rise and a 10% fall do not cancel out."),
    S(1, 2, "Profit and loss", "By selling an article for ₹1,064 a trader gains 12%. At what price should he sell it to gain 20%?",
      ["₹1,140", "₹1,149", "₹1,160", "₹1,120"],
      "Cost price = 1,064 ÷ 1.12 = ₹950. For a 20% gain he must sell at 950 x 1.2 = ₹1,140. Adding 8% to ₹1,064 gives about ₹1,149, which works on the wrong base."),
    S(1, 2, "Discount", "What single discount is equal to two successive discounts of 20% and 15%?",
      ["32%", "35%", "34%", "40%"],
      "After both discounts the buyer pays 0.80 x 0.85 = 0.68 of the price, so the single discount is 32%. Simply adding gives 35%, which overstates it."),
    S(1, 2, "Ratio and proportion", "The ratio of boys to girls in a class is 5 : 3. When 8 more girls join, the ratio becomes 5 : 4. How many boys are there?",
      ["40", "32", "24", "35"],
      "Let boys = 5x and girls = 3x. Then 5x ÷ (3x + 8) = 5/4, so 20x = 15x + 40 and x = 8. Boys = 40."),
    S(1, 2, "Averages", "The average age of 30 constables is 26 years. When the inspector's age is included, the average rises by 1 year. What is the inspector's age?",
      ["57 years", "56 years", "55 years", "27 years"],
      "31 people now average 27, a total of 837 years. The 30 constables total 780, so the inspector is 837 - 780 = 57. Shortcut: 27 + 30 x 1 = 57."),
    S(1, 2, "Simple interest", "A sum of money doubles itself in 8 years at simple interest. In how many years will it become four times itself?",
      ["24 years", "12 years", "16 years", "20 years"],
      "Doubling means interest of 100% in 8 years, so 12.5% a year. To become four times, the interest must be 300%, which takes 300 ÷ 12.5 = 24 years."),
    S(1, 2, "Compound interest", "What is the difference between the compound interest and the simple interest on ₹12,500 for 2 years at 6% per annum?",
      ["₹45", "₹30", "₹90", "₹750"],
      "For 2 years the difference is P x (R/100) squared = 12,500 x 0.06 x 0.06 = ₹45. It is the interest earned in year 2 on the first year's interest of ₹750. ₹90 doubles the correct figure."),
    S(1, 3, "Partnership", "A invests ₹40,000 and B invests ₹60,000 in a business. After 6 months A adds ₹20,000 more. Out of a year's profit of ₹33,000, what is A's share?",
      ["₹15,000", "₹18,000", "₹16,500", "₹22,000"],
      "A's capital-months = 40,000 x 6 + 60,000 x 6 = 6,00,000; B's = 60,000 x 12 = 7,20,000. The ratio is 5 : 6, so A gets 33,000 x 5/11 = ₹15,000."),
    S(1, 2, "Mixture and alligation", "In what ratio must wheat at ₹32 per kg be mixed with wheat at ₹47 per kg to get a mixture worth ₹38 per kg?",
      ["3 : 2", "2 : 3", "5 : 4", "9 : 4"],
      "By alligation, cheaper : dearer = (47 - 38) : (38 - 32) = 9 : 6 = 3 : 2. More of the cheaper wheat is needed because ₹38 is nearer ₹32."),
    S(1, 3, "Time and work", "A and B can finish a job in 12 days, B and C in 15 days, and A and C in 20 days. How long will A, B and C take working together?",
      ["10 days", "12 days", "15 days", "5 days"],
      "Adding the three pairs: 1/12 + 1/15 + 1/20 = 12/60 = 1/5, which is twice the work of A, B and C in a day. So together they do 1/10 a day and need 10 days."),
    S(1, 2, "Trains", "A train 240 m long passes a pole in 16 seconds. How long will it take to cross a platform 360 m long?",
      ["40 s", "24 s", "16 s", "36 s"],
      "Speed = 240 ÷ 16 = 15 m/s. To cross the platform it covers 240 + 360 = 600 m, which takes 600 ÷ 15 = 40 s. Using only the platform length gives 24 s."),
    S(1, 2, "Boats and streams", "A boat goes 42 km downstream in 3 hours and 20 km upstream in 2 hours. What is the speed of the stream?",
      ["2 km/h", "4 km/h", "5 km/h", "12 km/h"],
      "Downstream speed = 42 ÷ 3 = 14 km/h and upstream speed = 20 ÷ 2 = 10 km/h. Stream speed = (14 - 10) ÷ 2 = 2 km/h; the boat's own speed is 12 km/h. 4 km/h forgets to halve."),
    S(1, 1, "HCF and LCM", "The HCF of two numbers is 18 and their LCM is 540. If one number is 108, what is the other?",
      ["90", "72", "54", "36"],
      "The product of two numbers equals LCM x HCF, so the other number is 540 x 18 ÷ 108 = 90."),
    # ---------- Practice Test 2 ----------
    S(2, 2, "Percentage", "In an election between two candidates, the winner got 56% of the valid votes and won by 9,360 votes. How many valid votes were cast?",
      ["78,000", "70,000", "72,000", "84,000"],
      "The winner got 56% and the loser 44%, a margin of 12%. So 12% of the votes = 9,360 and the total = 9,360 ÷ 0.12 = 78,000."),
    S(2, 2, "Profit and loss", "A dealer marks his goods 35% above cost price and allows a discount of 12%. What is his profit percentage?",
      ["18.8%", "23%", "20%", "17.6%"],
      "Selling price = 1.35 x 0.88 = 1.188 times the cost price, a profit of 18.8%. Subtracting 12 from 35 gives 23%, which ignores that the discount is on the marked price."),
    S(2, 3, "Profit and loss", "A trader sells at cost price but uses a weight of 960 g in place of 1 kg. What is his gain percentage?",
      ["4 1/6%", "4%", "3 23/24%", "4 1/2%"],
      "He gives 960 g and is paid for 1,000 g, so he gains 40 g on 960 g. Gain = 40/960 x 100 = 4 1/6%. 4% wrongly divides by 1,000."),
    S(2, 2, "Ratio and proportion", "₹7,000 is divided among P, Q and R so that P : Q = 2 : 3 and Q : R = 4 : 5. What is R's share?",
      ["₹3,000", "₹2,400", "₹2,600", "₹1,600"],
      "Make Q the same in both ratios: P : Q = 8 : 12 and Q : R = 12 : 15, so P : Q : R = 8 : 12 : 15, 35 parts in all. R gets 7,000 x 15/35 = ₹3,000; Q gets ₹2,400."),
    S(2, 3, "Averages", "The average of 11 results is 50. The average of the first six is 49 and the average of the last six is 52. What is the sixth result?",
      ["56", "50", "52", "51"],
      "The first six total 294 and the last six total 312; together they count the sixth result twice. So the sixth = 294 + 312 - 550 = 56."),
    S(2, 1, "Simple interest", "₹8,000 amounts to ₹9,920 in 3 years at simple interest. What is the rate of interest per annum?",
      ["8%", "6%", "7.5%", "10%"],
      "Interest = 9,920 - 8,000 = ₹1,920. Rate = 1,920 x 100 ÷ (8,000 x 3) = 8%."),
    S(2, 2, "Compound interest", "At what rate of compound interest per annum will ₹10,000 become ₹12,100 in 2 years?",
      ["10%", "10.5%", "11%", "21%"],
      "12,100 ÷ 10,000 = 1.21, which is 1.1 squared, so the rate is 10%. 10.5% would be the simple-interest rate that gives the same amount."),
    S(2, 2, "Time and work", "A can do a piece of work in 10 days and B in 15 days. They work together and are paid ₹4,500. What is A's share?",
      ["₹2,700", "₹1,800", "₹2,250", "₹3,000"],
      "Wages follow the work done. A does 1/10 a day and B 1/15 a day, a ratio of 3 : 2. A gets 4,500 x 3/5 = ₹2,700."),
    S(2, 2, "Pipes and cisterns", "Pipe A can fill a tank in 14 hours and pipe B can empty it in 21 hours. If both are opened together, how long will the empty tank take to fill?",
      ["42 hours", "35 hours", "8.4 hours", "21 hours"],
      "Net filling per hour = 1/14 - 1/21 = 3/42 - 2/42 = 1/42 of the tank, so it fills in 42 hours. 8.4 hours wrongly adds the two rates."),
    S(2, 2, "Time and distance", "A car covers the first half of a journey at 36 km/h and the second half at 54 km/h. What is its average speed for the whole journey?",
      ["43.2 km/h", "45 km/h", "42 km/h", "44 km/h"],
      "For equal distances the average speed is 2 x 36 x 54 ÷ (36 + 54) = 3,888 ÷ 90 = 43.2 km/h. 45 km/h is the simple average of the speeds, which is wrong here."),
    S(2, 2, "Trains", "Two trains 160 m and 140 m long run in opposite directions at 42 km/h and 66 km/h. How long do they take to cross each other?",
      ["10 s", "12 s", "15 s", "45 s"],
      "Relative speed = 42 + 66 = 108 km/h = 30 m/s. They must cover 160 + 140 = 300 m, which takes 300 ÷ 30 = 10 s. 45 s would be the time if they ran in the same direction (24 km/h)."),
    S(2, 2, "HCF and LCM", "What is the smallest number that leaves a remainder of 5 when divided by 8, 12 or 18?",
      ["77", "72", "101", "149"],
      "The LCM of 8, 12 and 18 is 72, so the number is 72 + 5 = 77. 149 (144 + 5) also works but is not the smallest."),
    S(2, 2, "Square roots", "What is the value of √0.0169 x √1.44?",
      ["0.156", "1.56", "0.0156", "0.165"],
      "√0.0169 = 0.13 and √1.44 = 1.2, so the product is 0.13 x 1.2 = 0.156. Count the decimal places carefully."),
    # ---------- Drill only ----------
    S(0, 2, "Percentage", "The price of dal falls by 16 2/3%. By what percentage can a family increase the quantity it buys while spending the same amount?",
      ["20%", "16.67%", "15%", "12.5%"],
      "A fall of 1/6 means the price is 5/6 of what it was, so the same money buys 6/5 as much, an increase of 1/5 = 20%."),
    S(0, 3, "Profit and loss", "A sells an article to B at 10% profit and B sells it to C at 20% profit. If C pays ₹3,960, what did the article cost A?",
      ["₹3,000", "₹2,772", "₹3,168", "₹3,300"],
      "Price to C = cost x 1.1 x 1.2 = 1.32 x cost, so cost = 3,960 ÷ 1.32 = ₹3,000. ₹3,300 is only B's cost price."),
    S(0, 3, "Ratio and proportion", "Two numbers are in the ratio 3 : 5. If 9 is subtracted from each, the ratio becomes 12 : 23. What is the larger number?",
      ["55", "33", "45", "44"],
      "Let them be 3x and 5x. 23(3x - 9) = 12(5x - 9) gives 69x - 207 = 60x - 108, so 9x = 99 and x = 11. The numbers are 33 and 55."),
    S(0, 2, "Boats and streams", "A man rows at 9 km/h in still water and the stream flows at 3 km/h. How long will he take to row 24 km downstream and come back?",
      ["6 hours", "5.33 hours", "4 hours", "8 hours"],
      "Downstream speed 12 km/h takes 2 hours; upstream speed 6 km/h takes 4 hours. Total 6 hours. Using 9 km/h both ways gives 5.33 hours."),
]
